 elseif($action==='sent'){if(($_POST['sent_confirmed']??'')!=='yes')throw new RuntimeException('Підтвердьте фактичну ручну відправку.');shopDonationMarkSent($db,(int)($_POST['order_id']??0),$actor);$_SESSION['donation_notice']='Ручну відправку скріна позначено.';}
 else throw new RuntimeException('Невідома дія.');header('Location: /shop/donations.php',true,303);exit;
