$missing=$db->query("SELECT o.id FROM rubizh_customer_orders o LEFT JOIN rubizh_order_donations d ON d.order_id=o.id WHERE o.payment_status='paid' AND o.status NOT IN ('cancelled','returned') AND d.order_id IS NULL ORDER BY o.id DESC LIMIT 100")->fetchAll(PDO::FETCH_COLUMN);foreach($missing as $id)shopRecordPaid($db,(int)$id);
$rows=shopDonationRows($db);$pending=array_filter($rows,fn($r)=>$r['batch_id']===null);$sum=(int)array_sum(array_column($pending,'amount'));$groups=[];foreach($pending as $r){$c=json_decode($r['contact_json']??'{}',true);$brigade=shopDonationBrigade(is_array($c)?$c:[]);$groups[$brigade][]=$r;}$firstBrigade=array_key_first($groups);$selectedSum=$firstBrigade!==null?(int)array_sum(array_column($groups[$firstBrigade],'amount')):0;
