<?php if($error):?><p class="error" role="alert"><?=esc($error)?></p><?php endif;?><?php if($notice):?><p class="notice" role="status"><?=esc($notice)?></p><?php endif;?>
<section class="card"><h2>Чекають скріна · <?=count($rows)?></h2><p>До нового переказу: <strong><?=$sum?> ₴</strong>. Обрано: <strong id="selected-donation-sum"><?=$selectedSum?> ₴</strong>.</p>
