<?php foreach($groups as $brigade=>$group):?><fieldset class="card"><legend><?=esc($brigade)?></legend><p>Внески на цю бригаду: <?=(int)array_sum(array_column($group,'amount'))?> ₴</p>
<?php foreach($group as $r):?><label class="check <?=($r['due_at']<gmdate('Y-m-d H:i:s'))?'error':''?>"><input type="checkbox" name="orders[]" value="<?=(int)$r['order_id']?>" data-brigade="<?=esc($brigade)?>" data-amount="<?=(int)$r['amount']?>" <?=$brigade===$firstBrigade?'checked':''?>><span><?=esc($r['order_number'])?> · <?=(int)$r['amount']?> ₴ · до <?=esc(customerDate($r['due_at']))?><?=($r['due_at']<gmdate('Y-m-d H:i:s'))?' · ПРОСТРОЧЕНО':''?></span></label><?php endforeach;?></fieldset><?php endforeach;?>
<?php if($pending):?><div class="two"><label>Сума фактичного переказу, ₴<input id="donation-transfer-amount" type="number" name="amount" min="0" step="1" value="<?=$selectedSum?>" required></label><label>Дата і час переказу (Київ)<input type="datetime-local" name="transferred_at" value="<?=(new DateTimeImmutable('now',new DateTimeZone('Europe/Kyiv')))->format('Y-m-d\TH:i')?>" required></label></div><label>Номер або реквізит переказу<input name="reference" maxlength="240" minlength="4" required></label><label>Скрін переказу · PNG, JPG або WebP до 8 МБ<input type="file" name="screenshot" accept="image/png,image/jpeg,image/webp" required></label><label class="check"><input type="checkbox" name="transfer_confirmed" value="yes" required> Кошти фактично переказані на бригаду обраних замовлень; сума і скрін відповідають обраним замовленням</label><button>Прикріпити один скрін до обраних замовлень</button><?php else:?><p>Оплачених замовлень для нового переказу немає.</p><?php endif;?></form></section>
<section class="card"><h2>Переказано · чекають ручної відправки</h2><p>Відкрийте чат, прикріпіть завантажений скрін і текст. Кнопка чату не надсилає повідомлення та не позначає доставку.</p>
<?php foreach($rows as $r):if(!$r['batch_id'])continue;$c=json_decode($r['contact_json']??'{}',true)?:[];$chat=shopDonationChat($c,(int)$r['amount']);?><article class="card <?=($r['due_at']<gmdate('Y-m-d H:i:s'))?'error':''?>"><h3><a href="/shop/np-manager.php?order=<?=(int)$r['order_id']?>"><?=esc($r['order_number'])?></a> · <?=(int)$r['amount']?> ₴<?=($r['due_at']<gmdate('Y-m-d H:i:s'))?' · ПРОСТРОЧЕНО':''?></h3><p>Бригада: <?=esc(shopDonationBrigade($c))?></p><p>Переказ № <?=(int)$r['batch_id']?> · <?=esc($r['reference'])?> · <?=esc($chat['phone'])?> · <?=esc(ucfirst($chat['channel']))?></p><a class="button secondary" href="/shop/donation-proof.php?order=<?=(int)$r['order_id']?>&download=1">Завантажити скрін</a><?php if($chat['url']):?> <a class="button secondary" href="<?=esc($chat['url'])?>" target="_blank" rel="noopener">Відкрити <?=esc(ucfirst($chat['channel']))?></a><?php endif;?><label>Текст покупцю<textarea rows="3" readonly><?=esc($chat['text'])?></textarea></label><form method="post"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="order_id" value="<?=(int)$r['order_id']?>"><label class="check"><input type="checkbox" name="sent_confirmed" value="yes" required> Скрін і текст фактично надіслані покупцю</label><button name="action" value="sent">Позначити надісланим</button></form></article><?php endforeach;?></section>
<details class="card"><summary>Історія переказів та виключені після переказу замовлення</summary><?php foreach($db->query("SELECT b.id,b.amount,b.transferred_at,b.reference,COUNT(d.order_id) AS orders_count,SUM(CASE WHEN o.payment_status<>'paid' OR o.status IN ('cancelled','returned') THEN d.amount ELSE 0 END) AS excluded_amount FROM rubizh_donation_batches b JOIN rubizh_order_donations d ON d.batch_id=b.id JOIN rubizh_customer_orders o ON o.id=d.order_id GROUP BY b.id ORDER BY b.id DESC LIMIT 30")->fetchAll(PDO::FETCH_ASSOC) as $b):?><p>№ <?=(int)$b['id']?> · <?=(int)$b['amount']?> ₴ · <?=esc(customerDate($b['transferred_at']))?> · <?=esc($b['reference'])?> · замовлень: <?=(int)$b['orders_count']?><?php if((int)$b['excluded_amount']):?> · <strong class="error">Виключено після фактичного переказу: <?=(int)$b['excluded_amount']?> ₴. Перевірте повернення; здійснений переказ залишається в історії.</strong><?php endif;?></p><?php endforeach;?></details></main></body></html>
